// Validar si se puede cancelar (más de 24 horas antes)
// Luxon está disponible como variable global en n8n

const appointment = $json;
const cancelData = $('Process Cancel Confirm').first().json;
const staticData = $getWorkflowStaticData('global');
const businessConfig = staticData.businessConfig || {};

// Obtener fecha y hora de la cita
const appointmentDate = appointment.fecha; // formato: YYYY-MM-DD
const appointmentTime = appointment.hora; // formato: HH:MM

// Crear DateTime de la cita en zona horaria de Chile
const appointmentDateTime = DateTime.fromISO(`${appointmentDate}T${appointmentTime}:00`, { zone: 'America/Santiago' });

// Obtener hora actual de Chile usando Luxon (disponible globalmente en n8n)
const nowChile = DateTime.now().setZone('America/Santiago');

// Calcular diferencia en horas
const diffHours = appointmentDateTime.diff(nowChile, 'hours').hours;

// Verificar si faltan más de 24 horas
const canCancel = diffHours >= 24;

// Mensaje si no puede cancelar
const condicionCambios = businessConfig.pago_cambios;
const condicionReembolso = businessConfig.pago_reembolso;

const horasRestantes = Math.max(0, Math.round(diffHours * 10) / 10);
const errorMessage = `⚠️ *No es posible cancelar esta cita*\n\nTu cita es el ${appointment.fecha} a las ${appointment.hora} y faltan solo ${horasRestantes} horas (se requieren mínimo 24 horas de anticipación).\n\n📋 *Según nuestras condiciones:*\n\n🔄 ${condicionCambios}\n\n💰 ${condicionReembolso}\n\nSi tienes alguna emergencia, por favor comunícate directamente con nosotros.`;

return [{
  json: {
    ...appointment,
    canCancel,
    diffHours: Math.round(diffHours * 10) / 10,
    phoneNumber: cancelData.phoneNumber,
    phoneNumberId: cancelData.phoneNumberId,
    appointmentId: cancelData.appointmentId,
    newStatus: cancelData.newStatus,
    errorMessage,
    debugInfo: {
      nowChile: nowChile.toISO(),
      appointmentDateTime: appointmentDateTime.toISO(),
      diffHours: diffHours
    }
  }
}];

// Procesar respuesta a términos y condiciones
const payload = $('Combine Messages').first().json;
const { phoneNumber, phoneNumberId, contactName, textContent, businessPhone } = payload;
const staticData = $getWorkflowStaticData('global');

// Extraer ID de la cita y tipo de respuesta
const isAccept = textContent.startsWith('terms_accept_');
const isReject = textContent.startsWith('terms_reject_');
const appointmentId = textContent.replace('terms_accept_', '').replace('terms_reject_', '');

// Buscar el pago pendiente
const pendingPayment = staticData.pendingPayments?.[phoneNumber];

if (!pendingPayment) {
  return [{
    json: {
      action: 'expired',
      phoneNumber,
      phoneNumberId,
      businessPhone,
      message: 'Tu sesión ha expirado. Por favor escribe *agendar* para comenzar de nuevo.'
    }
  }];
}

if (isReject) {
  // Usuario rechazó los términos - cancelar reserva pendiente
  delete staticData.pendingPayments[phoneNumber];
  return [{
    json: {
      action: 'rejected',
      phoneNumber,
      phoneNumberId,
      businessPhone,
      contactName,
      message: 'Entendido. Tu reserva ha sido cancelada.\n\nSi cambias de opinión, escríbeme *agendar* para ver los horarios disponibles. 😊'
    }
  }];
}

if (isAccept) {
  // Usuario aceptó los términos - obtener configuración bancaria
  const config = staticData.businessConfig || {};

  // DEBUG: Log de la configuración para verificar
  console.log('CONFIG BANCARIA:', JSON.stringify(config, null, 2));
  console.log('tiene_cuenta2:', config.tiene_cuenta2);
  console.log('banco2_nombre:', config.banco2_nombre);

  // Construir mensaje con datos bancarios
  let bankMessage = '✅ *¡Términos Aceptados!*\n\n';
  bankMessage += 'Gracias por aceptar las condiciones. A continuación te comparto los datos para realizar la transferencia:\n\n';
  bankMessage += '━━━━━━━━━━━━━━━━━━━━\n\n';
  bankMessage += '🏦 *CUENTA BANCARIA 1:*\n\n';
  bankMessage += '👤 Nombre: ' + (config.banco_nombre || 'KELLYS TIRADO') + '\n';
  bankMessage += '🆔 RUT: ' + (config.banco_rut || '26.312.327-1') + '\n';
  bankMessage += '🏛️ Banco: ' + (config.banco_institucion || 'Banco Itaú') + '\n';
  bankMessage += '💳 Tipo: ' + (config.banco_tipo_cuenta || 'Cuenta Corriente') + '\n';
  bankMessage += '🔢 N° Cuenta: ' + (config.banco_numero || '0224080048') + '\n';
  bankMessage += '📧 Email: ' + (config.banco_email || 'KELLYSISABEL1504@GMAIL.COM') + '\n';

  // Si hay segunda cuenta bancaria - verificar ambas condiciones
  const hasCuenta2 = config.tiene_cuenta2 === true && config.banco2_nombre && config.banco2_nombre.trim() !== '';
  console.log('hasCuenta2 calculado:', hasCuenta2);

  if (hasCuenta2) {
    bankMessage += '\n━━━━━━━━━━━━━━━━━━━━\n\n';
    bankMessage += '🏦 *CUENTA BANCARIA 2 (Alternativa):*\n\n';
    bankMessage += '👤 Nombre: ' + config.banco2_nombre + '\n';
    bankMessage += '🆔 RUT: ' + config.banco2_rut + '\n';
    bankMessage += '🏛️ Banco: ' + config.banco2_institucion + '\n';
    bankMessage += '💳 Tipo: ' + config.banco2_tipo_cuenta + '\n';
    bankMessage += '🔢 N° Cuenta: ' + config.banco2_numero + '\n';
    bankMessage += '📧 Email: ' + config.banco2_email + '\n';
  }

  bankMessage += '\n━━━━━━━━━━━━━━━━━━━━\n\n';
  bankMessage += '📸 *IMPORTANTE:* Una vez realizada la transferencia, envía el comprobante (captura de pantalla) por este chat para confirmar tu reserva.\n\n';
  bankMessage += '⏰ Tienes 30 minutos para completar el pago, de lo contrario tu reserva será cancelada automáticamente.';

  return [{
    json: {
      action: 'accepted',
      phoneNumber,
      phoneNumberId,
      businessPhone,
      contactName,
      appointmentId: pendingPayment.appointmentId,
      message: bankMessage,
      debugConfig: config
    }
  }];
}

// Si no es ni accept ni reject
return [{
  json: {
    action: 'unknown',
    phoneNumber,
    phoneNumberId,
    businessPhone,
    message: 'No pude entender tu respuesta. Por favor usa los botones de Aceptar o No Acepto.'
  }
}];

