// ===========================================
// VALIDATE TRANSFER_ID UNIQUENESS AGAINST GOOGLE SHEETS
// ===========================================
const input = $json;
const transferId = input.transferId || input.validationResult?.transfer_id_normalized || '';
const phoneNumber = input.phoneNumber || '';
const businessPhone = input.businessPhone || '';

// Get all existing citas from Google Sheets (passed from previous node)
const allCitas = input.allCitas || [];

// Check if transfer_id already exists in any confirmed appointment
if (transferId) {
  const transferIdStr = String(transferId).trim();

  // Check against all confirmed citas in Google Sheets
  const duplicateInSheets = allCitas.some(cita => {
    const citaTransferId = String(cita.transfer_id || cita.id_transferencia || '').trim();
    const citaEstado = String(cita.estado || '').toLowerCase();
    return citaTransferId === transferIdStr && (citaEstado === 'confirmado' || citaEstado === 'pago validado');
  });

  if (duplicateInSheets) {
    return [{
      json: {
        error: true,
        mensaje: '❌ *Este ID de transferencia ya fue utilizado*\n\nNo puedes usar el mismo comprobante de pago dos veces. Por favor, verifica el número de transferencia e intenta con otro comprobante.',
        transferId: transferId,
        phoneNumber: phoneNumber,
        businessPhone: businessPhone,
        skipAppointment: true
      }
    }];
  }
}

// ===========================================
// PREPARE CONFIRMED APPOINTMENT FOR GOOGLE SHEETS
// ===========================================
const appointment = input.pendingAppointment;
const staticData = $getWorkflowStaticData('global');

// Clear pending payment and selection
if (staticData.pendingPayments) {
  delete staticData.pendingPayments[phoneNumber];
}
if (staticData.serviceSelections) {
  delete staticData.serviceSelections[phoneNumber];
}

// Get business config if available
const businessConfig = staticData.businessConfig || {};

// Get binary data (payment proof image)
const binaryData = $binary;

// Return data for Google Sheets with status CONFIRMED
return [{
  json: {
    id: appointment.id || appointment.appointmentId,
    nombre: appointment.nombre || appointment.contactName,
    email: '',
    telefono: appointment.telefono || phoneNumber,
    servicio: appointment.servicio,
    fecha: appointment.fecha || appointment.selectedDay,
    hora: appointment.hora,
    hora_fin: appointment.hora_fin,
    estado: 'Confirmado',
    precio: appointment.precio,
    notas: 'Pago validado automáticamente por IA - ' + new Date().toISOString(),
    creado: appointment.creado || appointment.createdAt || new Date().toISOString(),
    negocio_id: appointment.negocio_id || '1',
    negocio_email: businessConfig.email || 'Kellysisabel1504@gmail.com',
    negocio_nombre: businessConfig.nombre || 'Kells Capilar',
    displayDate: appointment.displayDate || appointment.fecha,
    transfer_id: transferId
  },
  binary: binaryData
}];

// Combinar datos de validación con citas existentes
const validationData = $('Validation Result').first().json;
const allCitasData = $input.all();

return [{
  json: {
    ...validationData,
    allCitas: allCitasData.map(item => item.json)
  }
}];

// ===========================================
// PROCESS VISION VALIDATION RESULT
// ===========================================
const visionResponse = $json;
const pendingData = $('Validate Payment Image').first().json;
const staticData = $getWorkflowStaticData('global');
const phoneNumber = pendingData.phoneNumber;

// Initialize cache on first use
if (!staticData.usedTransferIds) {
  staticData.usedTransferIds = {};
}

// DEDUPLICACIÓN: Verificar si ya procesamos esta imagen
if (!staticData.processedImages) staticData.processedImages = {};
const imageLink = pendingData.imageLink || '';
const imageHash = imageLink.split('/').pop() || imageLink;

if (staticData.processedImages[imageHash]) {
  return [{
    json: {
      isValid: false,
      isDuplicate: true,
      skipProcessing: true,
      phoneNumber: phoneNumber,
      message: 'Imagen ya procesada anteriormente'
    }
  }];
}

staticData.processedImages[imageHash] = Date.now();

// Limpiar imágenes procesadas antiguas (más de 1 hora)
const oneHourAgo = Date.now() - (60 * 60 * 1000);
Object.keys(staticData.processedImages).forEach(key => {
  if (staticData.processedImages[key] < oneHourAgo) {
    delete staticData.processedImages[key];
  }
});

// Parse GPT-4 Vision response
let validationResult;
try {
  const content = visionResponse.choices[0].message.content;
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    validationResult = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  validationResult = {
    valido: false,
    confianza: 'baja',
    razon: 'No se pudo analizar la imagen correctamente',
    fecha_valida: false,
    transfer_id: '',
    detalles: {}
  };
}

// NORMALIZAR TRANSFER_ID: Remover ceros a la izquierda
let normalizedTransferId = '';
if (validationResult.transfer_id) {
  const rawId = String(validationResult.transfer_id).trim();
  // Extraer solo números
  const numbersOnly = rawId.replace(/[^0-9]/g, '');
  // Remover ceros a la izquierda
  normalizedTransferId = String(parseInt(numbersOnly, 10) || numbersOnly).trim();
  validationResult.transfer_id_normalized = normalizedTransferId;
}

// USAR LA RAZÓN ORIGINAL DE GPT-4 (no sobrescribir)
const razonOriginal = validationResult.razon || '';

// Determine final result - usar los campos de validación de GPT-4
const isValid = validationResult.valido === true && 
                (validationResult.confianza === 'alta' || validationResult.confianza === 'media');

if (isValid) {
  if (staticData.pendingPayments) {
    delete staticData.pendingPayments[phoneNumber];
  }
}

const binaryData = $('Download Payment Image').first().binary;
const cuentasAutorizadas = pendingData.cuentasAutorizadas || [];

return [{
  json: {
    isValid: isValid,
    validationResult: validationResult,
    phoneNumber: phoneNumber,
    contactName: pendingData.contactName,
    phoneNumberId: pendingData.phoneNumberId,
    businessPhone: pendingData.businessPhone,
    pendingAppointment: pendingData.pendingAppointment,
    serviceName: pendingData.serviceName,
    appointmentDate: pendingData.appointmentDate,
    appointmentTime: pendingData.appointmentTime,
    imageLink: pendingData.imageLink,
    cuentasAutorizadas: cuentasAutorizadas,
    montoAbono: pendingData.montoAbono,
    transferId: normalizedTransferId
  },
  binary: binaryData
}];

// ===========================================
// VALIDATE PAYMENT IMAGE - Check if pending payment exists
// ===========================================
const input = $json;
const staticData = $getWorkflowStaticData('global');
const phoneNumber = input.phoneNumber;
const now = Date.now();

// Initialize pending payments if not exists
if (!staticData.pendingPayments) {
  staticData.pendingPayments = {};
}

// Get business config from staticData
const businessConfig = staticData.businessConfig || {};

// Check if there's a pending payment for this number
const pendingPayment = staticData.pendingPayments[phoneNumber];

if (!pendingPayment) {
  // No pending payment - this image is unrelated to payment
  return [{
    json: {
      hasPendingPayment: false,
      phoneNumber: phoneNumber,
      businessPhone: input.businessPhone,
      imageId: input.imageId || '',
      imageLink: input.imageLink || '',
      message: 'No hay un pago pendiente para validar.'
    }
  }];
}

// Check if payment expired (30 minutes timeout)
const thirtyMinutes = 30 * 60 * 1000;
const paymentTime = pendingPayment.createdAt || pendingPayment.timestamp || 0;
if (now - paymentTime > thirtyMinutes) {
  // Payment expired - delete and return error
  delete staticData.pendingPayments[phoneNumber];
  return [{
    json: {
      hasPendingPayment: false,
      paymentExpired: true,
      phoneNumber: phoneNumber,
      businessPhone: input.businessPhone,
      imageId: input.imageId || '',
      message: 'El tiempo para enviar el comprobante ha expirado (30 minutos). Por favor, vuelve a seleccionar tu horario.'
    }
  }];
}

// Build pendingAppointment object from stored data
const pendingAppointment = {
  id: pendingPayment.appointmentId,
  nombre: pendingPayment.contactName,
  telefono: pendingPayment.phoneNumber,
  servicio: pendingPayment.servicio,
  fecha: pendingPayment.selectedDay,
  displayDate: pendingPayment.displayDate,
  hora: pendingPayment.hora,
  hora_fin: pendingPayment.hora_fin,
  precio: pendingPayment.precio,
  duracion_min: pendingPayment.duracion_min,
  creado: new Date(pendingPayment.createdAt).toISOString()
};

// CONSTRUIR ARRAY DE CUENTAS DINÁMICAMENTE
const cuentasAutorizadas = [];

// Agregar cuenta 1 si existe
if (businessConfig.banco_nombre) {
  cuentasAutorizadas.push({
    id: 'cuenta1',
    nombre: businessConfig.banco_nombre,
    rut: businessConfig.banco_rut || '',
    banco: businessConfig.banco_institucion || '',
    tipoCuenta: businessConfig.banco_tipo_cuenta || 'Cuenta Corriente',
    numeroCuenta: businessConfig.banco_numero || '',
    email: businessConfig.banco_email || ''
  });
}

// Agregar cuenta 2 si existe
if (businessConfig.tiene_cuenta2 && businessConfig.banco2_nombre) {
  cuentasAutorizadas.push({
    id: 'cuenta2',
    nombre: businessConfig.banco2_nombre,
    rut: businessConfig.banco2_rut || '',
    banco: businessConfig.banco2_institucion || '',
    tipoCuenta: businessConfig.banco2_tipo_cuenta || 'Cuenta Corriente',
    numeroCuenta: businessConfig.banco2_numero || '',
    email: businessConfig.banco2_email || ''
  });
}

// Agregar cuenta 3 si existe (futuro)
if (businessConfig.banco3_nombre) {
  cuentasAutorizadas.push({
    id: 'cuenta3',
    nombre: businessConfig.banco3_nombre,
    rut: businessConfig.banco3_rut || '',
    banco: businessConfig.banco3_institucion || '',
    tipoCuenta: businessConfig.banco3_tipo_cuenta || 'Cuenta Corriente',
    numeroCuenta: businessConfig.banco3_numero || '',
    email: businessConfig.banco3_email || ''
  });
}

// Si no hay cuentas configuradas, usar fallback
if (cuentasAutorizadas.length === 0) {
  cuentasAutorizadas.push({
    id: 'cuenta1',
    nombre: 'KELLYS TIRADO',
    rut: '26.312.327-1',
    banco: 'Banco Itaú',
    tipoCuenta: 'Cuenta Corriente',
    numeroCuenta: '0224080048',
    email: 'KELLYSISABEL1504@GMAIL.COM'
  });
}

// Construir texto de cuentas para el prompt de GPT
let cuentasTexto = '';
cuentasAutorizadas.forEach((cuenta, index) => {
  cuentasTexto += 'CUENTA ' + (index + 1) + ':\n';
  cuentasTexto += '- Nombre: ' + cuenta.nombre + '\n';
  cuentasTexto += '- RUT: ' + cuenta.rut + '\n';
  cuentasTexto += '- Banco: ' + cuenta.banco + '\n';
  cuentasTexto += '- Tipo: ' + cuenta.tipoCuenta + '\n';
  cuentasTexto += '- Número: ' + cuenta.numeroCuenta + '\n';
  if (index < cuentasAutorizadas.length - 1) cuentasTexto += '\n';
});

// Pending payment exists and is valid - prepare for image validation
return [{
  json: {
    hasPendingPayment: true,
    phoneNumber: phoneNumber,
    contactName: pendingPayment.contactName || input.contactName,
    phoneNumberId: pendingPayment.phoneNumberId || input.phoneNumberId,
    businessPhone: input.businessPhone,
    imageId: input.imageId || '',
    imageLink: input.imageLink || '',
    imageMimeType: input.imageMimeType || 'image/jpeg',
    pendingAppointment: pendingAppointment,
    // Datos dinámicos de cuentas
    cuentasAutorizadas: cuentasAutorizadas,
    cuentasTexto: cuentasTexto,
    numeroCuentas: cuentasAutorizadas.length,
    montoAbono: businessConfig.pago_abono || '$20.000',
    // Mantener compatibilidad
    expectedBankDetails: {
      cuentas: cuentasAutorizadas,
      montoAbono: businessConfig.pago_abono || '$20.000'
    },
    paymentTimestamp: paymentTime,
    serviceName: pendingPayment.servicio,
    servicePrice: pendingPayment.precio,
    appointmentDate: pendingPayment.displayDate || pendingPayment.selectedDay,
    appointmentTime: pendingPayment.hora
  }
}];

