// Preparar cancelación - filtrar y mostrar solo citas FUTURAS del usuario
const { phoneNumber, phoneNumberId } = $('Parse Actions').first().json;
const phoneClean = String(phoneNumber).replace('+', '').replace(/\s/g, '');

// Obtener fecha y hora actual en Chile (UTC-3)
const now = new Date();
const chileTime = new Date(now.toLocaleString('en-US', { timeZone: 'America/Santiago' }));
const hoy = chileTime.toISOString().split('T')[0]; // YYYY-MM-DD
const horaActual = chileTime.getHours().toString().padStart(2, '0') + ':' + chileTime.getMinutes().toString().padStart(2, '0'); // HH:MM

// Filtrar citas: mismo teléfono, estado Confirmado, y fecha+hora > ahora
const appointments = $input.all().filter(item => {
  const apt = item.json;
  const aptPhone = String(apt.telefono).replace(/\s/g, '');
  const aptFecha = String(apt.fecha || '').trim();
  const aptHora = String(apt.hora || '00:00').trim();

  // Comparar fecha+hora vs fecha+hora actual
  const aptDateTime = aptFecha + ' ' + aptHora;
  const nowDateTime = hoy + ' ' + horaActual;

  // Solo citas futuras (fecha+hora mayor que ahora)
  const esFutura = aptDateTime > nowDateTime;

  return aptPhone === phoneClean && apt.estado === 'Confirmado' && apt.id && esFutura;
});

if (appointments.length === 0) {
  return [{ json: { phoneNumber, phoneNumberId, hasAppointment: false, appointmentCount: 0, message: 'No encontré citas activas asociadas a tu número.' } }];
}

// Ordenar por fecha y hora ascendente
appointments.sort((a, b) => {
  const fechaA = a.json.fecha + ' ' + a.json.hora;
  const fechaB = b.json.fecha + ' ' + b.json.hora;
  return fechaA.localeCompare(fechaB);
});

// Construir lista de citas para el mensaje
const citasList = appointments.map((item, idx) => {
  const apt = item.json;
  return `${idx + 1}. 📅 ${apt.fecha} | 🕐 ${apt.hora}-${apt.hora_fin} | 🛍️ ${apt.servicio}`;
}).join('\n');

// Construir rows para la lista interactiva (max 10)
const listRows = appointments.slice(0, 10).map(item => {
  const apt = item.json;
  return {
    id: `cancel_confirm_${apt.id}`,
    title: `${apt.fecha} ${apt.hora}`.slice(0, 24),
    description: `${apt.servicio} (${apt.hora}-${apt.hora_fin})`.slice(0, 72)
  };
});

const message = appointments.length === 1 
  ? `Encontré tu cita:\n\n📅 ${appointments[0].json.fecha}\n🕐 ${appointments[0].json.hora} - ${appointments[0].json.hora_fin}\n🛍️ ${appointments[0].json.servicio}\n\n¿Confirmas que deseas cancelarla?`
  : `Encontré ${appointments.length} citas activas:\n\n${citasList}\n\nSelecciona la cita que deseas cancelar:`;

return [{ 
  json: { 
    phoneNumber, 
    phoneNumberId, 
    hasAppointment: true, 
    appointmentCount: appointments.length,
    appointmentId: appointments[0].json.id,
    listRows,
    message
  } 
}];

// Procesar configuración de pago desde Google Sheets
const configRows = $input.all();
const config = {};

// Convertir filas a objeto key-value
configRows.forEach(item => {
  const parametro = item.json.parametro;
  const valor = item.json.valor;
  if (parametro && valor !== undefined) {
    config[parametro] = valor;
  }
});

// Función para parsear cuenta bancaria - soporta 2 formatos:
// Formato 1: Líneas simples (Nombre, RUT, Banco, Tipo, Número, Email)
// Formato 2: Con prefijos (Nombre: X, Rut: Y, Banco: Z, etc.)
function parseBankAccount(accountString) {
  if (!accountString) return null;
  const lines = accountString.split('\n').map(l => l.trim()).filter(l => l);
  if (lines.length < 5) return null;

  // Detectar si tiene formato con prefijos (contiene ':')
  const hasLabels = lines.some(l => l.includes(':'));

  if (hasLabels) {
    // Formato con prefijos: 'Nombre: LUIS MIGUEL...'
    const data = {};
    lines.forEach(line => {
      const colonIndex = line.indexOf(':');
      if (colonIndex > 0) {
        const key = line.substring(0, colonIndex).toLowerCase().trim();
        const value = line.substring(colonIndex + 1).trim();
        data[key] = value;
      }
    });
    return {
      nombre: data.nombre || data.name || '',
      rut: data.rut || '',
      banco: data.banco || data.bank || '',
      tipoCuenta: data.tipo || data['tipo cuenta'] || 'Cuenta Corriente',
      numero: data['número cuenta'] || data.numero || data['número'] || data.cuenta || '',
      email: data.correo || data.email || ''
    };
  } else {
    // Formato simple: líneas en orden
    return {
      nombre: lines[0] || '',
      rut: lines[1] || '',
      banco: lines[2] || '',
      tipoCuenta: lines[3] || '',
      numero: lines[4] || '',
      email: lines[5] || ''
    };
  }
}

// Parsear cuentas bancarias desde el formato multi-línea
const cuenta1 = parseBankAccount(config.negocio_cuenta_bancaria);
const cuenta2 = parseBankAccount(config.negocio_cuenta_bancaria2);

// Datos bancarios con fallback hardcodeado
const banco1 = cuenta1 || {
  nombre: 'KELLYS TIRADO',
  rut: '26.312.327-1',
  banco: 'Banco Itaú',
  tipoCuenta: 'Cuenta Corriente',
  numero: '0224080048',
  email: 'KELLYSISABEL1504@GMAIL.COM'
};

// Guardar en staticData para uso posterior
const staticData = $getWorkflowStaticData('global');
staticData.businessConfig = {
  nombre: config.negocio_nombre || 'Kells Capilar',
  email: config.negocio_email || 'Kellysisabel1504@gmail.com',
  direccion: config.negocio_direccion || '',
  telefono: config.negocio_telefono || '',
  // Datos bancarios cuenta 1
  banco_nombre: banco1.nombre,
  banco_rut: banco1.rut,
  banco_institucion: banco1.banco,
  banco_tipo_cuenta: banco1.tipoCuenta,
  banco_numero: banco1.numero,
  banco_email: banco1.email,
  // Datos bancarios cuenta 2 (opcional)
  banco2_nombre: cuenta2 ? cuenta2.nombre : '',
  banco2_rut: cuenta2 ? cuenta2.rut : '',
  banco2_institucion: cuenta2 ? cuenta2.banco : '',
  banco2_tipo_cuenta: cuenta2 ? cuenta2.tipoCuenta : '',
  banco2_numero: cuenta2 ? cuenta2.numero : '',
  banco2_email: cuenta2 ? cuenta2.email : '',
  tiene_cuenta2: cuenta2 !== null,
  // Condiciones de pago
  pago_abono: config.pago_abono,
  pago_condiciones: config.condiciones_agendamiento,
  pago_reembolso: config.condiciones_reembolso,
  pago_cambios: config.condiciones_cambios
};

// Pasar datos al siguiente nodo
const payload = $('Combine Messages').first().json;

return [{
  json: {
    ...payload,
    config: staticData.businessConfig
  }
}];

// Verificar límite de citas (máximo 3 por teléfono)
const MAX_APPOINTMENTS = 3;
const existingAppointments = $input.all();
const appointmentCount = existingAppointments.filter(item => item.json.id).length;

const payload = $('Combine Messages').first().json;
const { phoneNumber, phoneNumberId, contactName } = payload;

if (appointmentCount >= MAX_APPOINTMENTS) {
  return [{
    json: {
      phoneNumber,
      phoneNumberId,
      contactName,
      limitReached: true,
      appointmentCount,
      message: `⚠️ Has alcanzado el límite máximo de ${MAX_APPOINTMENTS} citas activas.\n\nPara agendar una nueva cita, primero debes cancelar alguna de tus citas existentes escribiendo *cancelar*.`
    }
  }];
}

return [{
  json: {
    phoneNumber,
    phoneNumberId,
    contactName,
    limitReached: false,
    appointmentCount
  }
}];

// Confirmar hora elegida - Crear cita PENDIENTE DE PAGO
// El usuario debe enviar comprobante de transferencia para confirmar

// Obtener datos del nodo anterior (Process Payment Config)
const inputData = $input.first().json;
const config = inputData.config || {};

const payload = $('Combine Messages').first().json;
const { phoneNumber, phoneNumberId, contactName } = payload;
const buttonId = String(payload.textContent || '');
const parts = buttonId.replace('time_', '').split('_');
const selectedDay = parts[0];
const startHHMM = parts[1].slice(0,2) + ':' + parts[1].slice(2);

const staticData = $getWorkflowStaticData('global');
const selectedService = staticData.selectedServiceByPhone?.[phoneNumber];

if (!selectedService) {
  return [{ json: { phoneNumber, phoneNumberId, error: 'NO_SERVICE', errorMessage: 'Tu sesión expiró. Por favor escribe *agendar* para comenzar de nuevo.' } }];
}

const dur = Number(selectedService.duracion_min || 30);
function toMinutes(hhmm){ const [h,m]=hhmm.split(':').map(Number); return h*60+m; }
function toHHMM(mins){ const h=Math.floor(mins/60); const m=mins%60; return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`; }
const endHHMM = toHHMM(toMinutes(startHHMM) + dur);

const appointmentId = Date.now().toString(36) + Math.random().toString(36).substr(2, 5);
const dateObj = new Date(selectedDay + 'T12:00:00');
const dayNames = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
const monthNames = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const displayDate = `${dayNames[dateObj.getDay()]} ${dateObj.getDate()} de ${monthNames[dateObj.getMonth()]}`;

// Guardar cita pendiente en staticData para validación posterior
if (!staticData.pendingPayments) staticData.pendingPayments = {};
staticData.pendingPayments[phoneNumber] = {
  appointmentId,
  contactName,
  phoneNumber,
  phoneNumberId,
  selectedDay,
  displayDate,
  hora: startHHMM,
  hora_fin: endHHMM,
  servicio: selectedService.nombre,
  duracion_min: dur,
  precio: selectedService.precio || '',
  createdAt: Date.now(),
  expiresAt: Date.now() + (30 * 60 * 1000) // Expira en 30 minutos
};

// Limpiar selección de servicio
delete staticData.selectedServiceByPhone[phoneNumber];

return [{ json: { 
  id: appointmentId,
  nombre: contactName,
  telefono: phoneNumber,
  fecha: selectedDay, 
  hora: startHHMM, 
  hora_fin: endHHMM, 
  servicio: selectedService.nombre,
  precio: selectedService.precio || '',
  estado: 'Pendiente Pago', 
  created_at: new Date().toISOString(),
  displayDate,
  duracion_min: dur,
  phoneNumberId,
  negocio_nombre: config.nombre || 'Nuestro negocio',
  negocio_direccion: config.direccion || '',
  negocio_maps: config.maps_url || '',
  negocio_email: config.email || '',
  // Datos bancarios desde configuración
  banco_nombre: config.banco_nombre || '',
  banco_rut: config.banco_rut || '',
  banco_institucion: config.banco_institucion || '',
  banco_tipo_cuenta: config.banco_tipo_cuenta || '',
  banco_numero: config.banco_numero || '',
  banco_email: config.banco_email || '',
  // Condiciones de pago
  pago_abono: config.pago_abono || '$20.000',
  pago_condiciones: config.pago_condiciones || '',
  pago_reembolso: config.pago_reembolso || '',
  pago_cambios: config.pago_cambios || '',
  awaitingPayment: true
} }];

