// Calcular slots disponibles (duración + horario + bloqueos + solapes)
// v6.1: Flexibilidad para servicios largos
// - Los bloqueos de horario (almuerzo, descansos) solo impiden INICIAR en ese rango
// - Los servicios pueden atravesar bloqueos de horario si inician antes
// - Los servicios pueden extenderse más allá del horario de cierre
// - ÚNICO BLOQUEANTE DURO: Citas existentes (no se pueden solapar)
function toMinutes(hhmm) { const [h, m] = String(hhmm).split(':').map(Number); return h * 60 + m; }
function toHHMM(mins) { const h = Math.floor(mins / 60); const m = mins % 60; return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`; }
function overlaps(aStart, aEnd, bStart, bEnd) { return aStart < bEnd && bStart < aEnd; }

const validationData = $('Validate Service Selection').first().json;
const { phoneNumber, phoneNumberId, selectedDay, selectedService } = validationData;

if (!selectedService) {
  return [{ json: { phoneNumber, phoneNumberId, selectedDay, listRows: [], slots: [], hasSlots: false, error: 'NO_SERVICE' } }];
}

const _staticDataPC = $getWorkflowStaticData('global');
const configRows = (_staticDataPC.portalConfig)
  ? _staticDataPC.portalConfig.configRows
  : $('Read Configuracion').all().map(i => i.json);
const config = configRows.reduce((acc, r) => { acc[r.parametro] = r.valor; return acc; }, {});
const horarioInicio = config.horario_inicio || '09:00';
const horarioFin = config.horario_fin || '18:00';
const bufferEntreCitas = Number(config.buffer_entre_citas || 0);

const openMin = toMinutes(horarioInicio);
const closeMin = toMinutes(horarioFin);
const serviceDuration = Number(selectedService.duracion_min || 30);

// Intervalo de 30 min para mostrar más opciones de horarios
const intervaloSlots = 30;

const blockRows = (_staticDataPC.portalConfig)
  ? _staticDataPC.portalConfig.bloqueos
  : $('Read Bloqueos').all().map(i => i.json);
// Filtrar citas por fecha y estado en código (sin filtro en Google Sheets)
const allCitas = $('Read Citas del Día').all().map(i => i.json);
const existing = allCitas.filter(c => c.fecha === selectedDay && c.estado === 'Confirmado');

// Bloqueos de horario: SOLO impiden que el servicio INICIE en ese rango
// Los servicios largos PUEDEN atravesarlos si inician antes
const softBlocks = [];

for (const b of blockRows) {
  const fecha = String(b.fecha || '').trim();
  const recurrente = String(b.recurrente || 'no').trim().toLowerCase();
  if (!b.hora_inicio || !b.hora_fin) continue;
  let applies = false;
  if (fecha === selectedDay) applies = true;
  else if (fecha === '*' && recurrente === 'diario') applies = true;
  else if (recurrente === 'anual' && fecha && fecha !== '*') { 
    const mmdd = selectedDay.slice(5); 
    applies = String(fecha).slice(5) === mmdd; 
  }
  if (!applies) continue;
  softBlocks.push({ start: toMinutes(b.hora_inicio), end: toMinutes(b.hora_fin) });
}

// CITAS EXISTENTES: ÚNICO BLOQUEANTE DURO - no se pueden solapar ni atravesar
const busy = [];
for (const a of existing) {
  if (!a.hora || !a.hora_fin) continue;
  const start = toMinutes(a.hora);
  const end = toMinutes(a.hora_fin);
  busy.push({ start: Math.max(openMin, start - bufferEntreCitas), end: Math.min(closeMin, end + bufferEntreCitas) });
}

const slots = [];
for (let start = openMin; start < closeMin; start += intervaloSlots) {
  const end = start + serviceDuration;

  // Bloqueos de horario: solo verificar que NO INICIE dentro del bloqueo
  // Permite atravesar si inicia antes
  if (softBlocks.some(r => start >= r.start && start < r.end)) continue;

  // CITAS EXISTENTES: Verificar traslape completo (ÚNICO BLOQUEANTE DURO)
  if (busy.some(r => overlaps(start, end, r.start, r.end))) continue;

  slots.push({ startMin: start, endMin: end, start: toHHMM(start), end: toHHMM(end), btnId: `time_${selectedDay}_${toHHMM(start).replace(':','')}` });
}

const dateObj = new Date(selectedDay + 'T12:00:00');
const dayNames = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
const monthNames = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const displayDate = `${dayNames[dateObj.getDay()]} ${dateObj.getDate()} de ${monthNames[dateObj.getMonth()]}`;

// Indicar si el servicio termina después del cierre
// NOTA: description oculta temporalmente - para reactivar cambiar '' por desc
const listRows = slots.slice(0, 10).map(s => {
  const terminaDespues = s.endMin > closeMin;
  const desc = terminaDespues ? `Termina ${s.end} (ext.)` : `Termina ${s.end}`;
  // Cambiar description: '' por description: desc para mostrar hora de término
  return { id: s.btnId, title: `${s.start} (${serviceDuration} min)`, description: '' };
});

const hasSlots = slots.length > 0;

// Guardar config del negocio en staticData para usarla en confirmación
const staticData = $getWorkflowStaticData('global');
staticData.businessConfig = {
  nombre: config.negocio_nombre || 'Nuestro negocio',
  direccion: config.negocio_direccion || '',
  maps_url: config.negocio_enlace_maps || '',
  email: config.negocio_email || ''
};

return [{ json: { phoneNumber, phoneNumberId, selectedDay, displayDate, selectedService, serviceDuration, slots, listRows, hasSlots } }];

// Validar que hay servicio seleccionado antes de procesar día
const payload = $('Combine Messages').first().json;
const { phoneNumber, phoneNumberId, textContent } = payload;
const selectedDay = String(textContent || '').replace('day_', '');

const staticData = $getWorkflowStaticData('global');
const selectedService = staticData.selectedServiceByPhone?.[phoneNumber];

if (!selectedService) {
  // No hay servicio seleccionado - redirigir a selección de servicios
  return [{ json: { phoneNumber, phoneNumberId, error: 'NO_SERVICE_SELECTED', needsServiceFirst: true } }];
}

// Validar que el servicio no expiró (más de 30 min)
if (Date.now() - selectedService.selectedAt > 1800000) {
  delete staticData.selectedServiceByPhone[phoneNumber];
  return [{ json: { phoneNumber, phoneNumberId, error: 'SERVICE_EXPIRED', needsServiceFirst: true } }];
}

return [{ json: { ...payload, selectedDay, selectedService } }];

